/**
 * parseDate
 *
 * @param {string} value - the date string to read, for example "2024-01-05".
 * @param {string} pattern - the strptime-style pattern that describes value.
 * @returns {Date} the parsed date, in the local time zone.
 */
function parseDate(value, pattern) {
  const [y, m, d] = value.split('-').map(Number);
  return new Date(y, m - 1, d);
}

