/**
 * slugify
 *
 * @param {string} text - the heading text to convert into a slug.
 */
function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

